        }
        startMissionAsyncNative(callback)
    }

    suspend fun pauseMission(): Result = suspendCancellableCoroutine { continuation ->
        val callback = PauseMissionCallback { result ->
            val r = Result.fromValue(result)
            if (r != Result.NEXT) {
